package com.example.aymobiledigitallibrary.ui.screens
import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.unit.dp;import com.example.aymobiledigitallibrary.data.LibraryItem;import com.example.aymobiledigitallibrary.model.*;import com.example.aymobiledigitallibrary.ui.components.*
@Composable fun RefindingTaskScreen(mode:BrowsingMode,allItems:List<LibraryItem>,targets:List<LibraryItem>,onDone:(List<RefindingResult>)->Unit){var trial by remember{ mutableIntStateOf(0)};var wrong by remember{ mutableIntStateOf(0)};var page by remember{ mutableIntStateOf(1)};var clicks by remember{ mutableIntStateOf(0)};var start by remember{ mutableLongStateOf(System.currentTimeMillis())};val state=rememberLazyListState();val out=remember{ mutableStateListOf<RefindingResult>()};val target=targets[trial];ScreenContainer{SectionTitle("Find This Material","Find the following material as quickly and accurately as possible.");Text(target.title);val shown=if(mode==BrowsingMode.PAGE_VIEW) allItems.filter{it.paginationPage==page} else allItems;LazyColumn(state=state,modifier=Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(10.dp)){items(shown){it2->LibraryItemCard(it2){if(it2.id==target.id){out+=RefindingResult(target.id,true,System.currentTimeMillis()-start,wrong,scrollCount=state.firstVisibleItemIndex,maxScrollDepth=(state.firstVisibleItemIndex/30f),pageClickCount=clicks,finalPage=page);if(trial==targets.lastIndex) onDone(out) else {trial++;wrong=0;clicks=0;page=1;start=System.currentTimeMillis()}} else wrong++}}};if(mode==BrowsingMode.PAGE_VIEW){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){SecondaryButton("Previous",{page--;clicks++},page>1);SecondaryButton("Next",{page++;clicks++},page<5)}}}}
